cat > $V/scripts/converter-export.mjs <<'EOF'
// Converte o export oficial do claude.ai (zip ou JSON em _raw/claude-export/**)
// em notas .md com frontmatter: claude/conversas/AAAA-MM/*.md e claude/projetos/<projeto>/*.md
// Idempotente: dedup por UUID (sobrescreve a nota com o mesmo source_id).
import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { RAIZ, slugify, dataISO, frontmatter, escrever, andar } from './lib.mjs';

const RAW = path.join(RAIZ, '_raw', 'claude-export');
const DEST_CONV = path.join(RAIZ, 'claude', 'conversas');
const DEST_PROJ = path.join(RAIZ, 'claude', 'projetos');

function extrairZips() {
  for (const zip of andar(RAW, p => p.endsWith('.zip'))) {
    const destino = zip.replace(/\.zip$/, '');
    if (fs.existsSync(destino)) continue;
    fs.mkdirSync(destino, { recursive: true });
    try {
      execFileSync('unzip', ['-o', '-q', zip, '-d', destino], { stdio: 'inherit' });
      console.log('extraído', path.relative(RAIZ, zip));
    } catch (e) {
      console.warn('não consegui extrair', zip, '(instale unzip ou extraia manualmente)');
    }
  }
}

function textoDaMensagem(msg) {
  if (typeof msg.text === 'string' && msg.text.trim()) return msg.text;
  if (Array.isArray(msg.content)) {
    return msg.content.map(b => {
      if (typeof b === 'string') return b;
      if (b.type === 'text') return b.text || '';
      if (b.type === 'tool_use') return `> 🔧 ferramenta: ${b.name || ''}`;
      if (b.type === 'tool_result') return '';
      return b.text || '';
    }).filter(Boolean).join('\n\n');
  }
  return '';
}

function indexarProjetos(projetos) {
  const porConversa = new Map();
  for (const p of projetos) {
    for (const c of p.conversations || p.chat_conversations || []) {
      const id = typeof c === 'string' ? c : c.uuid;
      if (id) porConversa.set(id, p.name);
    }
  }
  return porConversa;
}

function converterConversas(conversas, projetoDaConversa) {
  let n = 0;
  for (const c of conversas) {
    const msgs = c.chat_messages || c.messages || [];
    const data = dataISO(c.created_at) || dataISO(msgs[0]?.created_at) || '0000-00-00';
    const titulo = (c.name || '').trim() || (textoDaMensagem(msgs.find(m => m.sender === 'human') || {}) || 'Conversa sem título').slice(0, 80);
    const projeto = projetoDaConversa.get(c.uuid) || c.project?.name || null;
    const corpo = [];
    corpo.push(`# ${titulo}`, '');
    if (c.summary) corpo.push(`> **Resumo:** ${c.summary}`, '');
    corpo.push(`**Mensagens:** ${msgs.length} · **Criada:** ${data} · **Atualizada:** ${dataISO(c.updated_at) || '?'}`, '', '---', '');
    for (const m of msgs) {
      const quem = m.sender === 'human' ? '👤 Usuário' : '🤖 Claude';
      const quando = m.created_at ? new Date(m.created_at).toISOString().replace('T', ' ').slice(0, 16) : '';
      corpo.push(`## ${quem} ${quando ? `· ${quando}` : ''}`.trim(), '');
      corpo.push(textoDaMensagem(m) || '_(sem texto)_', '');
      const anexos = [...(m.attachments || []), ...(m.files || [])];
      for (const a of anexos) {
        const nome = a.file_name || a.name || 'anexo';
        corpo.push(`- 📎 ${nome}${a.file_type ? ` (${a.file_type})` : ''}`);
        if (a.extracted_content) corpo.push('', '```', String(a.extracted_content).slice(0, 20000), '```');
      }
      if (anexos.length) corpo.push('');
    }
    const fm = frontmatter({
      title: titulo,
      date: data,
      updated: dataISO(c.updated_at),
      source: 'claude-chat',
      source_id: c.uuid,
      url: `https://claude.ai/chat/${c.uuid}`,
      project: projeto,
      messages: msgs.length,
      tags: ['claude', 'conversa', ...(projeto ? ['projeto/' + slugify(projeto, 40)] : [])],
    });
    const arquivo = path.join(DEST_CONV, data.slice(0, 7), `${data}_${slugify(titulo, 60)}_${String(c.uuid).slice(0, 8)}.md`);
    escrever(arquivo, fm + corpo.join('\n'));
    n++;
  }
  return n;
}

function converterProjetos(projetos) {
  let n = 0;
  for (const p of projetos) {
    const pasta = path.join(DEST_PROJ, slugify(p.name, 60));
    const data = dataISO(p.created_at) || '0000-00-00';
    const corpo = [`# ${p.name}`, ''];
    if (p.description) corpo.push(p.description, '');
    if (p.prompt_template) corpo.push('## Instruções do projeto', '', p.prompt_template, '');
    const docs = p.docs || [];
    if (docs.length) {
      corpo.push('## Arquivos de conhecimento', '');
      for (const d of docs) {
        const nome = d.filename || d.name || 'documento';
        const arqDoc = `${slugify(nome, 60)}_${String(d.uuid || '').slice(0, 8)}.md`;
        corpo.push(`- [[${path.posix.join('claude/projetos', slugify(p.name, 60), arqDoc.replace(/\.md$/, ''))}|${nome}]]`);
        escrever(path.join(pasta, arqDoc), frontmatter({
          title: nome, date: dataISO(d.created_at) || data, source: 'claude-project-doc', source_id: d.uuid || null,
          project: p.name, tags: ['claude', 'projeto', 'conhecimento'],
        }) + `# ${nome}\n\n${d.content || ''}\n`);
      }
      corpo.push('');
    }
    escrever(path.join(pasta, '_projeto.md'), frontmatter({
      title: p.name, date: data, updated: dataISO(p.updated_at), source: 'claude-project', source_id: p.uuid,
      url: `https://claude.ai/project/${p.uuid}`, project: p.name, docs: docs.length, tags: ['claude', 'projeto'],
    }) + corpo.join('\n'));
    n++;
  }
  return n;
}

function main() {
  if (!fs.existsSync(RAW)) { console.log('nada em _raw/claude-export'); return; }
  extrairZips();
  const conversas = [], projetos = [];
  for (const arq of andar(RAW, p => p.endsWith('.json'))) {
    const nome = path.basename(arq);
    try {
      const dados = JSON.parse(fs.readFileSync(arq, 'utf8'));
      if (nome === 'conversations.json' && Array.isArray(dados)) conversas.push(...dados);
      else if (nome === 'projects.json' && Array.isArray(dados)) projetos.push(...dados);
      else if (nome === 'memories.json' || nome === 'users.json') {
        escrever(path.join(RAIZ, 'claude', nome.replace('.json', '.md')), frontmatter({ title: nome, source: 'claude-export', tags: ['claude'] }) + '```json\n' + JSON.stringify(dados, null, 2) + '\n```\n');
      }
    } catch (e) { console.warn('ignorado (JSON inválido):', nome); }
  }
  // dedup por uuid, mantendo a versão mais recente
  const porId = new Map();
  for (const c of conversas) { const ant = porId.get(c.uuid); if (!ant || (c.updated_at || '') > (ant.updated_at || '')) porId.set(c.uuid, c); }
  const nConv = converterConversas([...porId.values()], indexarProjetos(projetos));
  const nProj = converterProjetos(projetos);
  console.log(`conversas: ${nConv} · projetos: ${nProj}`);
}
main();
EOF
cat > $V/scripts/converter-sessao.mjs <<'EOF'
// Converte transcrições do Claude Code (.jsonl de ~/.claude/projects/**) em notas .md.
// Uso: node scripts/converter-sessao.mjs [arquivo.jsonl ...]   (sem args: tudo em _raw/sessoes-code/)
// Saída: claude/sessoes-code/AAAA-MM/AAAA-MM-DD_<titulo>_<id8>.md
import fs from 'node:fs';
import path from 'node:path';
import { RAIZ, slugify, dataISO, frontmatter, escrever, andar } from './lib.mjs';

const RAW = path.join(RAIZ, '_raw', 'sessoes-code');
const DEST = path.join(RAIZ, 'claude', 'sessoes-code');
const LIMITE_RESULTADO = 1500; // caracteres de saída de ferramenta mantidos na nota

function resumoInput(nome, input) {
  if (!input || typeof input !== 'object') return '';
  const chaves = ['command', 'description', 'file_path', 'pattern', 'query', 'url', 'prompt', 'path'];
  const partes = [];
  for (const k of chaves) if (input[k]) partes.push(`${k}: ${String(input[k]).replace(/\s+/g, ' ').slice(0, 300)}`);
  return partes.join(' · ');
}

function converter(arquivo) {
  const linhas = fs.readFileSync(arquivo, 'utf8').split('\n').filter(Boolean);
  let sessionId = null, titulo = null, cwd = null, modelo = null, custo = null, inicio = null, fim = null;
  const eventos = [];
  const ferramentas = new Map(); // tool_use_id -> nome
  let nThinking = 0;

  for (const l of linhas) {
    let ev; try { ev = JSON.parse(l); } catch { continue; }
    sessionId ||= ev.sessionId;
    if (ev.type === 'custom-title') { titulo = ev.customTitle; continue; }
    if (ev.type === 'cost-state') { custo = ev.totalCostUSD; continue; }
    if (ev.type === 'attachment') {
      if (ev.attachment?.type === 'environment') cwd = ev.attachment.snapshot?.workingDirectory;
      if (ev.attachment?.type === 'model') modelo = ev.attachment.identity?.modelId;
      continue;
    }
    if (ev.type !== 'user' && ev.type !== 'assistant') continue;
    if (ev.timestamp) { inicio ||= ev.timestamp; fim = ev.timestamp; }
    const conteudo = ev.message?.content;
    const blocos = typeof conteudo === 'string' ? [{ type: 'text', text: conteudo }] : Array.isArray(conteudo) ? conteudo : [];
    for (const b of blocos) {
      if (b.type === 'thinking') { nThinking++; continue; }
      if (b.type === 'text' && b.text?.trim()) {
        if (ev.type === 'user' && /^<(system-reminder|task-notification|local-command)/.test(b.text.trim())) continue;
        eventos.push({ papel: ev.type, texto: b.text, side: ev.isSidechain, ts: ev.timestamp });
      } else if (b.type === 'tool_use') {
        ferramentas.set(b.id, b.name);
        eventos.push({ papel: 'tool_use', nome: b.name, resumo: resumoInput(b.name, b.input), side: ev.isSidechain, ts: ev.timestamp });
      } else if (b.type === 'tool_result') {
        const txt = typeof b.content === 'string' ? b.content : Array.isArray(b.content) ? b.content.map(x => x.text || '').join('\n') : '';
        eventos.push({ papel: 'tool_result', nome: ferramentas.get(b.tool_use_id) || '?', texto: txt, erro: b.is_error, side: ev.isSidechain });
      }
    }
  }
  if (!eventos.length) return null;

  const primeiroUsuario = eventos.find(e => e.papel === 'user' && !e.side)?.texto || 'Sessão Claude Code';
  titulo ||= primeiroUsuario.replace(/\s+/g, ' ').slice(0, 80);
  const data = dataISO(inicio) || '0000-00-00';
  const repo = cwd ? path.basename(cwd) : null;
  const nTools = eventos.filter(e => e.papel === 'tool_use').length;

  const corpo = [`# ${titulo}`, ''];
  corpo.push(`**Repositório:** ${repo || '?'} · **Início:** ${inicio?.replace('T', ' ').slice(0, 16) || '?'} · **Fim:** ${fim?.replace('T', ' ').slice(0, 16) || '?'} · **Ferramentas chamadas:** ${nTools} · **Blocos de raciocínio omitidos:** ${nThinking}`, '');
  corpo.push('> Transcrição bruta completa em `_raw/sessoes-code/`. Saídas de ferramentas estão truncadas aqui.', '', '---', '');
  for (const e of eventos) {
    const marcaSide = e.side ? ' _(subagente)_' : '';
    if (e.papel === 'user') corpo.push(`## 👤 Usuário${marcaSide}`, '', e.texto.trim(), '');
    else if (e.papel === 'assistant') corpo.push(`## 🤖 Claude${marcaSide}`, '', e.texto.trim(), '');
    else if (e.papel === 'tool_use') corpo.push(`> 🔧 **${e.nome}**${marcaSide}${e.resumo ? ` — ${e.resumo.replace(/\n/g, ' ')}` : ''}`, '');
    else if (e.papel === 'tool_result') {
      const t = (e.texto || '').trim();
      if (!t) continue;
      const cortado = t.length > LIMITE_RESULTADO ? t.slice(0, LIMITE_RESULTADO) + `\n… (${t.length - LIMITE_RESULTADO} caracteres omitidos)` : t;
      corpo.push(`<details><summary>${e.erro ? '❌' : '📄'} resultado de ${e.nome}</summary>`, '', '```', cortado.replace(/```/g, "'''"), '```', '', '</details>', '');
    }
  }
  const fm = frontmatter({
    title: titulo, date: data, source: 'claude-code', source_id: sessionId,
    url: sessionId ? `https://claude.ai/code/${sessionId}` : null, repo, cwd, model: modelo,
    cost_usd: custo != null ? Math.round(custo * 100) / 100 : null, tool_calls: nTools,
    raw: path.posix.join('_raw/sessoes-code', path.basename(arquivo)),
    tags: ['claude', 'claude-code', ...(repo ? ['repo/' + slugify(repo, 40)] : [])],
  });
  const destino = path.join(DEST, data.slice(0, 7), `${data}_${slugify(titulo, 50)}_${String(sessionId || 'x').slice(0, 8)}.md`);
  escrever(destino, fm + corpo.join('\n'));
  return destino;
}

const args = process.argv.slice(2);
const arquivos = args.length ? args : [...andar(RAW, p => p.endsWith('.jsonl'))];
let n = 0;
for (const a of arquivos) {
  // se veio de fora do vault, guarda cópia bruta primeiro
  if (!path.resolve(a).startsWith(RAW)) {
    const copia = path.join(RAW, path.basename(a));
    fs.mkdirSync(RAW, { recursive: true }); fs.copyFileSync(a, copia);
  }
  const r = converter(a); if (r) { n++; console.log('→', path.relative(RAIZ, r)); }
}
console.log(`sessões convertidas: ${n}`);
