cat > $V/.github/workflows/sincronizar.yml <<'EOF'
name: Sincronizar segundo cérebro

on:
  schedule:
    - cron: "17 6 * * 1"        # segunda-feira, 06:17 UTC
  workflow_dispatch:
  push:
    paths:
      - "_raw/**"
      - "codigo/repos.json"
      - "scripts/**"

permissions:
  contents: write

concurrency:
  group: sincronizar
  cancel-in-progress: false

jobs:
  sincronizar:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-node@v4
        with:
          node-version: 22
      - name: Converter export do claude.ai (se houver)
        run: node scripts/converter-export.mjs
      - name: Converter sessões do Claude Code (se houver)
        run: node scripts/converter-sessao.mjs
      - name: Anotar artifacts
        run: node scripts/importar-artifacts.mjs
      - name: Importar docs dos repositórios
